final class NagramiXPiPResourceLoader: NSObject, AVAssetResourceLoaderDelegate {
    let asset: AVURLAsset
    private let queue = DispatchQueue(label: "NagramiX.PiP.resource")
    private let mediaBox: MediaBox
    private let reference: MediaResourceReference
    private let location: MediaResourceUserLocation
    private let contentType: MediaResourceUserContentType
    private let length: Int64
    private let uti: String
    private var requests: [ObjectIdentifier: DisposableSet] = [:]

    init(mediaBox: MediaBox, reference: MediaResourceReference, location: MediaResourceUserLocation, contentType: MediaResourceUserContentType, length: Int64, mimeType: String) {
        self.mediaBox = mediaBox
        self.reference = reference
        self.location = location
        self.contentType = contentType
        self.length = length
        self.uti = mimeType == "video/quicktime" ? "com.apple.quicktime-movie" : "public.mpeg-4"
        self.asset = AVURLAsset(url: URL(string: "nagramix-pip://media/video")!)
        super.init()
        self.asset.resourceLoader.setDelegate(self, queue: self.queue)
    }

    func resourceLoader(_ resourceLoader: AVAssetResourceLoader, shouldWaitForLoadingOfRequestedResource loadingRequest: AVAssetResourceLoadingRequest) -> Bool {
        let key = ObjectIdentifier(loadingRequest)
        if let info = loadingRequest.contentInformationRequest {
            info.contentType = self.uti
            info.contentLength = self.length
            info.isByteRangeAccessSupported = true
        }
        guard let dataRequest = loadingRequest.dataRequest else {
            loadingRequest.finishLoading()
            return true
        }
        let requestedStart = dataRequest.requestedOffset
        let requestedLength = Int64(dataRequest.requestedLength)
        guard requestedStart >= 0, requestedStart <= self.length, requestedLength >= 0 else {
            loadingRequest.finishLoading(with: NSError(domain: "NagramiXPiPStream", code: 1))
            return true
        }
        let end = dataRequest.requestsAllDataToEndOfResource ? self.length : min(self.length, requestedStart + min(requestedLength, self.length - requestedStart))
        self.requests[key] = DisposableSet()
        self.read(loadingRequest, end: end, key: key)
        return true
    }

    private func read(_ request: AVAssetResourceLoadingRequest, end: Int64, key: ObjectIdentifier) {
        guard let set = self.requests[key], let dataRequest = request.dataRequest else { return }
        let start = max(dataRequest.requestedOffset, dataRequest.currentOffset)
        if start >= end {
            self.requests.removeValue(forKey: key)?.dispose()
            request.finishLoading()
            return
        }
        let stop = start + min(end - start, 1024 * 1024)
        let range = start ..< stop
        let fetch = fetchedMediaResource(mediaBox: self.mediaBox, userLocation: self.location, userContentType: self.contentType, reference: self.reference, range: (range, .elevated), reportResultStatus: true, continueInBackground: true).start(error: { [weak self, weak request, weak set] _ in
            self?.queue.async {
                guard let self, let request, let set, self.requests[key] === set else { return }
                self.requests.removeValue(forKey: key)?.dispose()
                request.finishLoading(with: NSError(domain: "NagramiXPiPStream", code: 2))
            }
        })
        set.add(fetch)
        let data = (self.mediaBox.resourceData(self.reference.resource, size: self.length, in: range, mode: .complete) |> filter { $0.1 } |> take(1)).start(next: { [weak self, weak request, weak set] bytes, complete in
            guard complete else { return }
            self?.queue.async {
                guard let self, let request, let set, let dataRequest = request.dataRequest, self.requests[key] === set else { return }
                guard bytes.count == Int(stop - start) else {
                    self.requests.removeValue(forKey: key)?.dispose()
                    request.finishLoading(with: NSError(domain: "NagramiXPiPStream", code: 3))
                    return
                }
                self.requests.removeValue(forKey: key)?.dispose()
                self.requests[key] = DisposableSet()
                dataRequest.respond(with: bytes)
                self.read(request, end: end, key: key)
            }
        })
        set.add(data)
    }

    func resourceLoader(_ resourceLoader: AVAssetResourceLoader, didCancel loadingRequest: AVAssetResourceLoadingRequest) {
        self.requests.removeValue(forKey: ObjectIdentifier(loadingRequest))?.dispose()
    }

    func cancelAll() {
        self.queue.async {
            for item in self.requests.values { item.dispose() }
            self.requests.removeAll()
        }
    }
}
final class NagramiXPiPResourceLoader: NSObject, AVAssetResourceLoaderDelegate {
    private final class PendingRequest {
        // AVFoundation's request must live until finishLoading or didCancel.
        let request: AVAssetResourceLoadingRequest
        let end: Int64
        var work = DisposableSet()
        init(_ request: AVAssetResourceLoadingRequest, end: Int64) {
            self.request = request
            self.end = end
        }
    }
    let asset: AVURLAsset
    private let queue = DispatchQueue(label: "NagramiX.PiP.resource")
    private let mediaBox: MediaBox
    private let reference: MediaResourceReference
    private let location: MediaResourceUserLocation
    private let contentType: MediaResourceUserContentType
    private let length: Int64
    private let uti: String
    private var requests: [ObjectIdentifier: PendingRequest] = [:]
    private var cancelled = false
    private var metadataRequests = 0
    private var dataRequests = 0
    private var deliveredBytes: Int64 = 0
    private var lastFailure = "нет"

    var diagnostic: String {
        return self.queue.sync {
            "метаданные=\(self.metadataRequests), запросы=\(self.dataRequests), байты=\(self.deliveredBytes), ожидают=\(self.requests.count), ошибка=\(self.lastFailure)"
        }
    }
    init(mediaBox: MediaBox, reference: MediaResourceReference, location: MediaResourceUserLocation, contentType: MediaResourceUserContentType, length: Int64, mimeType: String) {
        self.mediaBox = mediaBox
        self.reference = reference
        self.location = location
        self.contentType = contentType
        self.length = length
        self.uti = mimeType == "video/quicktime" ? "com.apple.quicktime-movie" : "public.mpeg-4"
        let pathExtension = mimeType == "video/quicktime" ? "mov" : "mp4"
        self.asset = AVURLAsset(url: URL(string: "nagramix-pip://media/\(UUID().uuidString).\(pathExtension)")!)
        super.init()
        self.asset.resourceLoader.setDelegate(self, queue: self.queue)
    }

    func resourceLoader(_ resourceLoader: AVAssetResourceLoader, shouldWaitForLoadingOfRequestedResource loadingRequest: AVAssetResourceLoadingRequest) -> Bool {
        guard !self.cancelled else {
            loadingRequest.finishLoading(with: NSError(domain: NSURLErrorDomain, code: NSURLErrorCancelled))
            return true
        }
        if let info = loadingRequest.contentInformationRequest {
            self.metadataRequests += 1
            info.contentType = self.uti
            info.contentLength = self.length
            info.isByteRangeAccessSupported = true
            // The initial content-info probe may also contain a two-byte data
            // request. Complete metadata independently; AVFoundation requests
            // the actual media ranges after it knows the type and length.
            loadingRequest.finishLoading()
            return true
        }
        guard let dataRequest = loadingRequest.dataRequest else {
            loadingRequest.finishLoading()
            return true
        }
        self.dataRequests += 1
        let start = dataRequest.requestedOffset
        let count = Int64(dataRequest.requestedLength)
        guard start >= 0, start <= self.length, count >= 0 else {
            self.lastFailure = "некорректный диапазон"
            loadingRequest.finishLoading(with: NSError(domain: "NagramiXPiPStream", code: 1))
            return true
        }
        let end = dataRequest.requestsAllDataToEndOfResource ? self.length : start + min(count, self.length - start)
        let key = ObjectIdentifier(loadingRequest)
        let pending = PendingRequest(loadingRequest, end: end)
        self.requests[key] = pending
        self.read(pending, key: key)
        return true
    }

    private func fail(_ pending: PendingRequest, key: ObjectIdentifier, code: Int, reason: String) {
        guard self.requests[key] === pending else { return }
        self.lastFailure = reason
        self.requests.removeValue(forKey: key)
        pending.work.dispose()
        pending.request.finishLoading(with: NSError(domain: "NagramiXPiPStream", code: code))
    }

    private func read(_ pending: PendingRequest, key: ObjectIdentifier) {
        guard self.requests[key] === pending, let dataRequest = pending.request.dataRequest else { return }
        let start = max(dataRequest.requestedOffset, dataRequest.currentOffset)
        if start >= pending.end {
            self.requests.removeValue(forKey: key)
            pending.work.dispose()
            pending.request.finishLoading()
            return
        }
        // Deliver small ranges promptly, including moov metadata at the end
        // of a file. Never wait for an entire megabyte before feeding AVPlayer.
        let stop = start + min(pending.end - start, 64 * 1024)
        let range = start ..< stop
        let fetch = fetchedMediaResource(mediaBox: self.mediaBox, userLocation: self.location, userContentType: self.contentType, reference: self.reference, range: (range, .elevated), reportResultStatus: true, continueInBackground: true).start(error: { [weak self, weak pending] _ in
            guard let self else { return }
            self.queue.async { [weak self, weak pending] in
                guard let self, let pending else { return }
                self.fail(pending, key: key, code: 2, reason: "загрузка диапазона")
            }
        })
        pending.work.add(fetch)
        let data = (self.mediaBox.resourceData(self.reference.resource, size: self.length, in: range, mode: .complete) |> filter { $0.1 } |> take(1)).start(next: { [weak self, weak pending] bytes, complete in
            guard complete, let self else { return }
            self.queue.async { [weak self, weak pending] in
                guard let self, let pending, self.requests[key] === pending,
                      let dataRequest = pending.request.dataRequest else { return }
                guard bytes.count == Int(stop - start) else {
                    self.fail(pending, key: key, code: 3, reason: "неполный диапазон")
                    return
                }
                pending.work.dispose()
                pending.work = DisposableSet()
                self.deliveredBytes += Int64(bytes.count)
                dataRequest.respond(with: bytes)
                self.read(pending, key: key)
            }
        })
        pending.work.add(data)
    }

    func resourceLoader(_ resourceLoader: AVAssetResourceLoader, didCancel loadingRequest: AVAssetResourceLoadingRequest) {
        self.requests.removeValue(forKey: ObjectIdentifier(loadingRequest))?.work.dispose()
    }

    func cancelAll() {
        self.queue.async {
            self.cancelled = true
            let pending = Array(self.requests.values)
            self.requests.removeAll()
            for item in pending {
                item.work.dispose()
                item.request.finishLoading(with: NSError(domain: NSURLErrorDomain, code: NSURLErrorCancelled))
            }
        }
    }
}
